import { atom, read, update } from 'claude-code'
import type { Register, EngineInterface, TextProps, ToolCallInput, ToolResultOf } from 'claude-code'

import type { LiveThought, ShowMode, StoredDiff, StoredThought } from '../types'

// 运行时模式：存 $.state；null 表示"未设置"，读时回落到清单配置值。
const mode = atom({ plugin: 'show-mode', key: 'mode' } as const, null as ShowMode | null)

// hidden 模式下保存文件 diff 和思考过程，off 不新增记录。
const diffs = atom({ plugin: 'show-mode', key: 'diffs' } as const, [] as StoredDiff[])
const thoughts = atom({ plugin: 'show-mode', key: 'thoughts' } as const, [] as StoredThought[])
const liveThought = atom({ plugin: 'show-mode', key: 'liveThought' } as const, null as LiveThought | null)
const processRows = atom(
  { plugin: 'show-mode', key: 'processRows' } as const,
  {} as Record<string, boolean>,
)

// 按主会话/子代理隔离。只有随后确实调用了工具的正文，才标记为过程叙述。
const pending = new Map<string, Map<string, string>>()
const loopKey = (agentId?: string) => agentId ?? 'main'

const DIFF_LIMIT = 100
const THOUGHT_LIMIT = 100
const VIEW_LIMIT = 10
const VIEW_ALL_LIMIT = 30
const THOUGHT_LINE_LIMIT = 5
const ROW_LIMIT = 2000

// 时:分:秒，记录的时间戳。
const stamp = (at: number) => {
  const d = new Date(at)
  const p = (n: number) => String(n).padStart(2, '0')

  return `${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`
}

const MODES: readonly ShowMode[] = ['off', 'hidden']

const MODE_LABEL: Record<ShowMode, string> = {
  off: '正常显示',
  hidden: '仅展示当前思考',
}

const parseMode = (text: string): ShowMode | null => {
  const lower = text.trim().toLowerCase()

  return MODES.includes(lower as ShowMode) ? (lower as ShowMode) : null
}

type DiffEntry = Omit<StoredDiff, 'id' | 'at'>
type Hunk = ToolResultOf<'Write'>['structuredPatch'][number]

const diffHeaders = (filePath: string, created: boolean) =>
  `--- ${created ? '/dev/null' : JSON.stringify(filePath)}\n+++ ${JSON.stringify(filePath)}\n`

const formatPatch = (filePath: string, created: boolean, hunks: readonly Hunk[]) =>
  diffHeaders(filePath, created) + hunks.map((hunk) =>
    `@@ -${hunk.oldStart},${hunk.oldLines} +${hunk.newStart},${hunk.newLines} @@\n${hunk.lines.join('\n')}\n`,
  ).join('')

// 引擎未返回 hunk、但提供了完整前后内容时，生成完整文件替换 diff。
// 不依赖 Git，因此新文件、未暂存文件和非 Git 目录均可回看。
const contentLines = (content: string) => {
  if (content === '') return []
  const lines = content.split('\n')
  if (content.endsWith('\n')) lines.pop()
  return lines
}

const fullDiff = (filePath: string, created: boolean, before: string, after: string) => {
  const oldLines = contentLines(before)
  const newLines = contentLines(after)
  const removed = oldLines.map((line) => `-${line}`)
  const added = newLines.map((line) => `+${line}`)
  if (before !== '' && !before.endsWith('\n')) removed.push('\\ No newline at end of file')
  if (after !== '' && !after.endsWith('\n')) added.push('\\ No newline at end of file')
  if (oldLines.length === 0 && newLines.length === 0) return diffHeaders(filePath, created)
  return formatPatch(filePath, created, [{
    oldStart: oldLines.length === 0 ? 0 : 1,
    oldLines: oldLines.length,
    newStart: newLines.length === 0 ? 0 : 1,
    newLines: newLines.length,
    lines: [...removed, ...added],
  }])
}

const collectDiffs = (tool: string, output: unknown): DiffEntry[] => {
  if (!output || typeof output !== 'object') return []

  if (tool === 'Write' || tool === 'Edit') {
    const result = output as ToolResultOf<'Write'> | ToolResultOf<'Edit'>
    // staged 表示等待机器所有者审阅，文件尚未写入。
    if (result.staged || typeof result.filePath !== 'string') return []
    const write = 'content' in result ? result : undefined
    const created = write?.type === 'create'
    const before = created ? '' : result.originalFile
    const after = 'content' in result ? result.content : typeof before === 'string'
      ? result.replaceAll
        ? before.split(result.oldString).join(result.newString)
        : before.replace(result.oldString, () => result.newString)
      : null
    const hunks = result.structuredPatch
    if (!created && (!Array.isArray(hunks) || hunks.length === 0)
      && typeof before === 'string' && before === after) return []
    const diff = Array.isArray(hunks) && hunks.length > 0
      ? formatPatch(result.filePath, created, hunks)
      : typeof before === 'string' && typeof after === 'string'
        ? fullDiff(result.filePath, created, before, after)
        : '文件已修改，但工具未提供可用的 diff 或完整修改前内容。'
    return [{ filePath: result.filePath, action: created ? 'create' : 'update', tool, diff }]
  }

  if (tool === 'Bash') {
    // 仅使用引擎明确归属于本次命令的文件 diff，避免混入用户已有的工作区修改。
    const result = output as ToolResultOf<'Bash'>
    return (result.bashEditDiff?.files ?? [])
      .filter((file) => !file.deleted && (file.created || file.hunks.length > 0))
      .map((file) => ({
        filePath: file.filePath,
        action: file.created ? 'create' as const : 'update' as const,
        tool,
        diff: formatPatch(file.filePath, Boolean(file.created), file.hunks),
      }))
  }
  return []
}

// 每次文件更新独立记录，最多保留最近 100 条，超出时删除最旧记录。
const storeDiffs = async ($: EngineInterface, entries: DiffEntry[]) => {
  if (entries.length === 0) return
  try {
    if ((parseMode((await read($, mode)) ?? '') ?? configured) !== 'hidden') return
    const at = Date.now()
    await update($, diffs, (list) => {
      const firstId = list.length > 0 ? list[list.length - 1]!.id + 1 : 1
      const next = [...list, ...entries.map((entry, index) => ({ ...entry, id: firstId + index, at }))]
      return next.slice(-DIFF_LIMIT)
    })
  } catch {
    // 归档失败不能把已经成功的文件更新报告成失败。
    $.ui.log('show-mode：文件 diff 保存失败', { to: 'debug' })
  }
}

const formatEntry = (entry: StoredDiff) =>
  `── code #${entry.id} ── ${stamp(entry.at)} ── ${entry.action === 'create' ? '新增' : '修改'} ── ${entry.tool}\n${entry.filePath}\n${entry.diff}`

type DiffStyle = 'plain' | 'record' | 'file' | 'hunk' | 'added' | 'removed' | 'context'

const DIFF_STYLES: Record<DiffStyle, TextProps> = {
  plain: {},
  record: { color: 'cyan', bold: true },
  file: { color: 'yellow' },
  hunk: { color: 'cyan' },
  added: { color: 'green' },
  removed: { color: 'red' },
  context: { dimColor: true },
}

// 仅解析回看输出的副本，保存的 diff 保持纯文本。
// hunk 内的 +++ / --- 也可能是代码内容，必须按增删行处理。
const diffRuns = (text: string) => {
  const runs: { style: DiffStyle; text: string }[] = []
  let inHunk = false
  let filePathNext = false
  for (const [index, line] of text.split(/\r?\n/).entries()) {
    let style: DiffStyle = 'plain'
    if (/^── code #\d+ ── /.test(line)) {
      style = 'record'
      inHunk = false
      filePathNext = true
    } else if (filePathNext) {
      style = 'file'
      filePathNext = false
    } else if (/^@@ -\d+(?:,\d+)? \+\d+(?:,\d+)? @@/.test(line)) {
      style = 'hunk'
      inHunk = true
    } else if (inHunk) {
      style = line.startsWith('+') ? 'added'
        : line.startsWith('-') ? 'removed' : 'context'
    } else if (line.startsWith('--- ') || line.startsWith('+++ ')) {
      style = 'file'
    }

    // 相邻同样式的行合并，避免大 diff 为每行创建一个渲染节点。
    const content = (index === 0 ? '' : '\n') + line
    const previous = runs[runs.length - 1]
    if (previous?.style === style) previous.text += content
    else runs.push({ style, text: content })
  }
  return runs
}

// 标题另计；正文最多五行，省略提示也放在第五行内。
const limitThought = (text: string) => {
  const lines = text.replace(/\r\n?|\u2028|\u2029/g, '\n')
    .replace(/^\n+|\n+$/g, '').split('\n')
  if (lines.length <= THOUGHT_LINE_LIMIT) return lines.join('\n')
  const kept = lines.slice(0, THOUGHT_LINE_LIMIT)
  kept[THOUGHT_LINE_LIMIT - 1] += ' …（后续省略）'
  return kept.join('\n')
}

const showThought = async ($: EngineInterface, kind: LiveThought['kind'], text: string, agentId?: string) => {
  if (text.trim() === '' || (parseMode((await read($, mode)) ?? '') ?? configured) !== 'hidden') return
  const visible = limitThought(text)
  await update($, liveThought, (previous) =>
    previous?.kind === kind && previous.agentId === agentId && previous.text === visible
      ? previous : { kind, text: visible, ...(agentId === undefined ? {} : { agentId }) })
}

// 尚未跟随工具调用的正文是最终回答候选，结束/切换模式时恢复其原生显示。
const releasePending = async ($: EngineInterface, key?: string) => {
  const ids = key === undefined
    ? [...pending.values()].flatMap((rows) => [...rows.keys()])
    : [...(pending.get(key)?.keys() ?? [])]
  if (key === undefined) pending.clear()
  else pending.delete(key)
  if (ids.length === 0) return
  await update($, processRows, (known) => {
    const remaining = { ...known }
    for (const id of ids) delete remaining[id]
    return remaining
  })
}

const THOUGHT_LABEL: Record<StoredThought['kind'], string> = {
  thinking: '思考',
  narration: '过程叙述',
  tool: '工具调用',
  skill: '技能调用',
}

// tool.call 的参数与 tool 同级；所有工具（包括只读工具和 MCP）都归入 think。
const formatToolCall = (e: ToolCallInput) => {
  const args = Object.entries(e)
    .filter(([key]) => !['tool', 'tool_use_id', 'agentId', 'consent'].includes(key))
    .map(([key, value]) => `${key}: ${typeof value === 'string' ? value : JSON.stringify(value)}`)
  return `${e.tool}\n${args.join('\n')}`
}

// think 同样最多保存最近 100 条，工具/技能调用计入这一上限。
const storeThoughts = async (
  $: EngineInterface,
  kind: StoredThought['kind'],
  texts: string[],
) => {
  const entries = texts.filter((text) => text.trim() !== '').map(limitThought)
  if (entries.length === 0) return
  try {
    if ((parseMode((await read($, mode)) ?? '') ?? configured) !== 'hidden') return
    const at = Date.now()
    await update($, thoughts, (list) => {
      const firstId = list.length > 0 ? list[list.length - 1]!.id + 1 : 1
      const next = [...list, ...entries.map((text, index) => ({
        id: firstId + index, at, kind, text,
      }))]
      return next.slice(-THOUGHT_LIMIT)
    })
  } catch {
    $.ui.log('show-mode：思考过程保存失败', { to: 'debug' })
  }
}

const formatThought = (entry: StoredThought) =>
  `── think #${entry.id} ── ${stamp(entry.at)} ── ${THOUGHT_LABEL[entry.kind]}\n${limitThought(entry.text)}`

// /show-mode status 按需查看，避免在每个分片上弹 toast。
const stats: {
  starts: number
  fires: number
  chunks: number
  completes: number
  appends: number
  tools: number
  renders: number
  kinds: Record<string, number>
} = { starts: 0, fires: 0, chunks: 0, completes: 0, appends: 0, tools: 0, renders: 0, kinds: {} }

const markProcess = async ($: EngineInterface, agentId?: string) => {
  const key = loopKey(agentId)
  const rows = pending.get(key)
  if (!rows?.size) return

  // 先取走这一批，避免并行工具重复归档同一段正文。
  pending.delete(key)
  if ((parseMode((await read($, mode)) ?? '') ?? configured) !== 'hidden') return
  await update($, processRows, (known) => {
    const next = { ...known }
    for (const id of rows.keys()) next[id] = true
    const ids = Object.keys(next)
    for (const id of ids.slice(0, Math.max(0, ids.length - ROW_LIMIT))) delete next[id]
    return next
  })
  await storeThoughts($, 'narration', [...rows.values()])
}

// 清单配置的默认模式，register 时赋值
let configured: ShowMode = 'hidden'

export const register: Register = (on, options) => {
  configured = parseMode(String(options.mode ?? '')) ?? 'hidden'

  // 会话开始：注册 /show-mode 命令
  on('session.start', async ($, e, next) => {
    await releasePending($)
    await update($, liveThought, () => null)
    await $.command.register({
      name: 'show-mode',
      description: '切换过程显示，回看或清空 hidden 模式保存的文件 diff 和思考过程',
      argumentHint: 'off|hidden|status|view [code|think|all|clear]',
    })

    return next(e)
  })

  // /show-mode：
  // - view：两类各最近 10 条；view code / view think：查看对应类型最近 10 条
  // - view all：两类各最近 30 条；view clear：清空两类保存记录
  // - 只有显式 off / hidden 才切换模式；无参数仅提示用法
  on('command.run', { command: 'show-mode' }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()

    // 回看不受当前显示模式限制，off 仍可以查看之前保存的记录。
    if (arg === 'view' || arg.startsWith('view ')) {
      const rest = arg.slice(4).trim()
      if (rest === 'clear') {
        await update($, diffs, () => [])
        await update($, thoughts, () => [])
        return { text: 'show-mode：已清空全部文件更新 diff 和 think 记录' }
      }
      if (!['', 'code', 'think', 'all'].includes(rest)) {
        return { text: '用法：/show-mode view [code|think|all|clear]；默认每类最近 10 条，all 每类最近 30 条，clear 清空全部记录' }
      }
      const limit = rest === 'all' ? VIEW_ALL_LIMIT : VIEW_LIMIT
      // 先取最近记录再格式化，避免为未展示的历史 diff 创建大字符串。
      const files = rest === 'think' ? [] : ((await read($, diffs)) ?? []).slice(-limit)
      const thinking = rest === 'code' ? [] : ((await read($, thoughts)) ?? []).slice(-limit)
      const records = [
        ...files.map((entry) => ({ kind: 'code', at: entry.at, text: formatEntry(entry) })),
        ...thinking.map((entry) => ({ kind: 'think', at: entry.at, text: formatThought(entry) })),
      ].sort((a, b) => a.at - b.at)
      if (records.length === 0) {
        const label = rest === 'code' ? '文件更新 diff' : rest === 'think' ? '思考过程' : '文件更新或思考过程'
        return { text: `show-mode：暂无保存的${label}` }
      }
      const counts = [
        rest === 'think' ? '' : `文件更新 ${files.length} 条`,
        rest === 'code' ? '' : `思考过程 ${thinking.length} 条`,
      ].filter(Boolean).join('，')
      // 纯文本输出也保留块间空行：think 前一行，code 前两行。
      const content = records.map((entry) =>
        `${entry.kind === 'code' ? '\n\n\n' : '\n\n'}${entry.text.replace(/\n+$/, '')}`,
      ).join('')
      return { text: `show-mode 最近的记录（${counts}；每类最多 ${limit} 条）：${content}` }
    }

    const current = parseMode((await read($, mode)) ?? '') ?? configured
    const wanted = parseMode(arg)
    if (arg !== 'status' && wanted === null) {
      return { text: '用法：/show-mode off|hidden|status|view [code|think|all|clear]；切换模式必须指定 off 或 hidden' }
    }
    const picked = arg === 'status'
      ? current
      : wanted!

    if (arg !== 'status') {
      if (picked !== current) {
        await releasePending($)
        await update($, liveThought, () => null)
      }
      await update($, mode, () => picked)
      $.ui.toast(`show-mode: ${picked} (${MODE_LABEL[picked]})`)
    }

    const list = (await read($, diffs)) ?? []
    const thinking = (await read($, thoughts)) ?? []
    const rows = (await read($, processRows)) ?? {}
    const kinds = Object.entries(stats.kinds)
      .map(([k, n]) => `${k}=${n}`)
      .join(' ')

    return {
      text: `show-mode ${arg === 'status' ? '当前为' : '已切换为'} ${picked} (${MODE_LABEL[picked]})；已识别 ${Object.keys(rows).length} 条过程消息，已存文件 diff ${list.length} 条、思考过程 ${thinking.length} 条（/show-mode view 回看）；仅 hidden 模式新增记录\n诊断：start=${stats.starts} / append=${stats.appends} / tool=${stats.tools} / AssistantMessage=${stats.renders} / complete=${stats.completes}\nturn.step=${stats.fires} / 分片=${stats.chunks} (${kinds || '无'})`,
    }
  })

  // view / view code / view think / view all 共用无缩进的布局和块间空白。
  // 用原生 Text 着色；命令输出的存档和复制内容不包含 ANSI 控制字符。
  on('ui.render', { component: 'CommandOutput' }, async ($, e, next) => {
    const arg = e.props.args.trim().toLowerCase()
    const isView = arg === 'view'
      || (arg.startsWith('view ') && ['code', 'think', 'all'].includes(arg.slice(4).trim()))
    if (e.props.command !== 'show-mode' || e.props.isErrored
      || !isView
      || !/(?:^|\n)── (?:code|think) #\d+ ── /.test(e.props.text)) return next(e)

    // 每条记录分别渲染，思考正文中的 + / - 不参与 diff 着色。
    const sections = e.props.text.replace(/\r\n/g, '\n').split(
      /(?=^── (?:code|think) #\d+ ── \d{2}:\d{2}:\d{2} ── )/m,
    )
    const { Box, Text } = $.ui.resolve(e)
    return <Box flexDirection="column" marginLeft={0} paddingLeft={0}>
      {sections.map((value, index) => {
        // 分隔空行交给 Box 的 marginTop，避免 Markdown 吞掉它们。
        const section = value.replace(/\n+$/, '')
        if (/^── code #\d+ ── /.test(section)) {
          return <Box key={String(index)} flexDirection="column" marginTop={2} paddingLeft={0}>
            <Text wrap="wrap">{diffRuns(section).map((run, runIndex) =>
              <Text key={String(runIndex)} {...DIFF_STYLES[run.style]}>{run.text}</Text>,
            )}</Text>
          </Box>
        }
        if (/^── think #\d+ ── /.test(section)) {
          const end = section.indexOf('\n')
          const title = end === -1 ? section : section.slice(0, end)
          const body = end === -1 ? '' : limitThought(section.slice(end + 1))
          return <Box key={String(index)} flexDirection="column" marginTop={1} paddingLeft={0}>
            <Text color="magenta" bold wrap="wrap">{title}</Text>
            {body !== '' && body.split('\n').map((line, lineIndex) =>
              // 每行单独截断，确保长参数/正文不会自动折成超过五行。
              <Text key={String(lineIndex)} wrap="truncate-end" dimColor>{line || ' '}</Text>,
            )}
          </Box>
        }
        return <Text key={String(index)} wrap="wrap" dimColor>{section}</Text>
      })}
    </Box>
  })

  // 新回合不继承上一轮的候选正文，避免把上一轮最终回答隐藏掉。
  on('turn.start', async ($, e, next) => {
    await releasePending($)
    await update($, liveThought, () => null)
    stats.starts += 1
    return next(e)
  })

  // append 提供实际消息 UUID，对应 AssistantMessage 的 requestId。
  // 正文和 tool_use 可能分开存储，因此还会在 tool.call 时归类。
  on('session.append', async ($, e, next) => {
    if (e.door !== 'response' || e.message.type !== 'assistant') return next(e)
    stats.appends += 1
    const key = loopKey(e.agentId)
    const current = parseMode((await read($, mode)) ?? '') ?? configured
    if (current !== 'hidden') {
      await releasePending($, key)
      return next(e)
    }
    const text = e.message.content
      .filter((block) => block.type === 'text' && typeof block.text === 'string')
      .map((block) => block.text as string)
      .join('\n\n')
    if (text.trim() !== '') {
      const rows = pending.get(key) ?? new Map<string, string>()
      rows.set(e.uuid, text)
      pending.set(key, rows)
      // append 落盘前就隐藏候选行，避免先显示一遍、工具开始后再消失。
      await update($, processRows, (known) => {
        const marked = { ...known, [e.uuid]: true }
        for (const id of Object.keys(marked).slice(0, -ROW_LIMIT)) delete marked[id]
        return marked
      })
      await showThought($, 'narration', text, e.agentId)
    }
    if (e.message.content.some((block) => block.type === 'tool_use')) {
      await markProcess($, e.agentId)
    }
    return next(e)
  })

  on('tool.call', async ($, e, next) => {
    stats.tools += 1
    const current = parseMode((await read($, mode)) ?? '') ?? configured
    await markProcess($, e.agentId)
    if (current === 'hidden') {
      try {
        // 在执行前记录调用，保留嵌套技能/工具的发起顺序。
        await storeThoughts($, e.tool === 'Skill' ? 'skill' : 'tool', [formatToolCall(e)])
      } catch {
        $.ui.log(`show-mode：无法记录 ${e.tool} 调用`, { to: 'debug' })
      }
    }
    const result = await next(e)
    if (current === 'hidden' && result.deny === undefined && !result.isError && !result.isReadOnly) {
      try {
        await storeDiffs($, collectDiffs(e.tool, result.result))
      } catch {
        $.ui.log(`show-mode：无法解析 ${e.tool} 返回的文件 diff`, { to: 'debug' })
      }
    }
    return result
  })

  // 过程及候选正文在临时区域显示；回合结束后恢复最终回答的原生渲染。
  on('ui.render', { component: 'AssistantMessage' }, async ($, e, next) => {
    stats.renders += 1
    const current = parseMode((await read($, mode)) ?? '') ?? configured
    if (current === 'off') return next(e)
    const rows = await read($, processRows)
    if (!rows[e.requestId]) return next(e)

    const { Box } = $.ui.resolve(e)
    return <Box display="none" />
  })

  // thinking 通过唯一的临时区域显示，下一块替换上一块，步骤结束时保留。
  // text/tool/input/engine/stop 全部按原顺序透传；签名思考仍由引擎保存。
  on('turn.step', async function* ($, e, next) {
    stats.fires += 1
    const blocks = new Map<number, string>()
    try {
      for await (const c of next(e)) {
        stats.chunks += 1
        stats.kinds[c.kind] = (stats.kinds[c.kind] ?? 0) + 1
        if (c.kind === 'thinking') {
          const current = parseMode((await read($, mode)) ?? '') ?? configured
          if (current === 'hidden') {
            const text = (blocks.get(c.index) ?? '') + c.text
            blocks.set(c.index, text)
            await showThought($, 'thinking', text, e.agentId)
          } else {
            yield c
          }
        } else {
          yield c
        }
      }
    } finally {
      // 流中断时也保留已收到的思考；保存前再次检查模式。
      await storeThoughts($, 'thinking', [...blocks.values()])
    }
  })

  // 最后没有跟随工具调用的正文保留为回答；中断时也保留现有正文。
  on('turn.complete', async ($, e, next) => {
    stats.completes += 1
    await releasePending($, loopKey(e.agentId))
    // 子代理完成时只清理自己的预览，主回合结束则清理整个临时区域。
    await update($, liveThought, (visible) =>
      e.agentId === undefined || visible?.agentId === e.agentId ? null : visible)
    return next(e)
  })

  on('classic.SessionStart', async ($, e, next) => {
    await releasePending($)
    await update($, liveThought, () => null)
    return next(e)
  })

  // ToolGroup：批量汇总行（Thought for 13s, searched for 2 patterns...）
  on('ui.render', { component: 'ToolGroup' }, async ($, e, next) => {
    const current = parseMode((await read($, mode)) ?? '') ?? configured

    if (current === 'off') {
      return next(e)
    }

    // hidden：整行不画
    const { Box } = $.ui.resolve(e)
    return <Box display="none" />
  })

  // ToolUse：单个调用行（含 Skill 调用）
  on('ui.render', { component: 'ToolUse' }, async ($, e, next) => {
    const current = parseMode((await read($, mode)) ?? '') ?? configured

    if (current === 'off') {
      return next(e)
    }

    // hidden：成功、失败和被中断的调用都不画。
    const { Box } = $.ui.resolve(e)
    return <Box display="none" />
  })

  // ToolResult：结果块
  // hidden 下隐藏所有结果，包括错误输出。
  on('ui.render', { component: 'ToolResult' }, async ($, e, next) => {
    const current = parseMode((await read($, mode)) ?? '') ?? configured

    if (current === 'off') {
      return next(e)
    }

    const { Box } = $.ui.resolve(e)
    return <Box display="none" />
  })

  // ToolProgress：工具运行提示（ctrl+b to run in background）。
  on('ui.render', { component: 'ToolProgress' }, async ($, e, next) => {
    const current = parseMode((await read($, mode)) ?? '') ?? configured
    if (current === 'off') return next(e)

    const { Box } = $.ui.resolve(e)
    return <Box display="none" />
  })

  // Spinner：回合进行中的状态行（Swirling… (46s · ↓ 1.1k tokens)）
  // 思考正文与原生状态行放在同一列，状态行始终在思考正文之后。
  on('ui.render', { component: 'Spinner' }, async ($, e, next) => {
    const current = parseMode((await read($, mode)) ?? '') ?? configured
    const visible = await read($, liveThought)
    const status = await next(e)
    if (current !== 'hidden' || !visible) return status
    const { Box, Text } = $.ui.resolve(e)
    return <Box flexDirection="column" paddingLeft={0} marginTop={1}>
      {visible.text.split('\n').map((line, index) =>
        <Text key={String(index)} wrap="truncate-end" dimColor>{line || ' '}</Text>,
      )}
      {status}
    </Box>
  })
}

